Intro paragraph: what this page looks at and why.
Select which stations to include, and hover over a chart to compare the match day to the baseline in 10-minute blocks.
Plot = import("https://cdn.jsdelivr.net/npm/@observablehq/plot@0.6.16/+esm")

lines   = transpose(lines_data)
bins    = transpose(bins_data)
matches = transpose(matches_data)

colors = ({"Match day": "#ee3124", "Baseline": "#8A8A8A"})

fmtTime = m =&gt;
  `${String(Math.floor(m / 60) % 24).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`

minToLabel = m =&gt; {
  const h = Math.floor(m / 60) % 24;
  return `${h % 12 === 0 ? 12 : h % 12} ${h &lt; 12 ? "am" : "pm"}`;
}

legend = () =&gt; html`&lt;div class="chart-legend"&gt;
  ${Object.entries(colors).map(([k, c]) =&gt;
    html`&lt;span&gt;&lt;span class="key" style="background:${c}"&gt;&lt;/span&gt;${k}&lt;/span&gt;`)}
&lt;/div&gt;`

function matchChart(m, area, w) {
  const d = lines.filter(r =&gt; r.match_id === m.match_id && r.area === area);
  if (d.length === 0) {
    return html`&lt;p class="text-muted fst-italic my-4"&gt;No data for this match / area yet.&lt;/p&gt;`;
  }
  const b = bins.filter(r =&gt; r.match_id === m.match_id && r.area === area);
  const ymax = d3.max(d, r =&gt; r.smooth) * 1.1;

  const plot = Plot.plot({
    width: w, height: 320,
    marginLeft: 50, marginRight: 25, marginBottom: 45,
    x: {domain: [m.x0, m.x1], ticks: d3.range(Math.ceil(m.x0 / 60) * 60, m.x1 + 1, 60),
        tickFormat: minToLabel, label: "Departure time",
        labelAnchor: "center", labelArrow: "none", labelOffset: 38},
    y: {domain: [0, ymax], grid: true, label: "Bixi trips per minute",
        labelAnchor: "center", labelArrow: "none"},
    color: {domain: Object.keys(colors), range: Object.values(colors)},
    marks: [
      Plot.rect([m], {x1: "ko", x2: "fw", y1: 0, y2: ymax,
                      fill: "#F2E8C9", fillOpacity: 0.6}),
      Plot.text([m], {x: r =&gt; (r.ko + r.fw) / 2, y: ymax, dy: 10,
                      text: () =&gt; "Match", fill: "#7A6A3A", fontSize: 12}),
      // highlighted bin under the pointer; drives the tooltip below
      Plot.rect(b, Plot.pointerX({x1: "bin", x2: r =&gt; r.bin + hover_bin,
                                  y1: 0, y2: ymax, px: r =&gt; r.bin + hover_bin / 2,
                                  maxRadius: Infinity,
                                  fill: "currentColor", fillOpacity: 0.06})),
      Plot.line(d, {x: "minute", y: "smooth", z: "series", stroke: "series",
                    strokeWidth: 1.6}),
      Plot.ruleY([0])
    ]
  });

  const tip  = html`&lt;div class="hover-tip"&gt;&lt;/div&gt;`;
  const wrap = html`&lt;div class="plot-wrap"&gt;${plot}${tip}&lt;/div&gt;`;
  const sign = v =&gt; (v &gt;= 0 ? "+" : "");

  wrap.addEventListener("pointermove", e =&gt; {
    tip.style.top = `${e.clientY - wrap.getBoundingClientRect().top}px`;
  });

  plot.addEventListener("input", () =&gt; {
    const v = plot.value;
    if (!v) { tip.style.display = "none"; return; }
    const mid   = v.bin + hover_bin / 2;
    const scale = plot.getBoundingClientRect().width / w;  // svg may be shrunk
    const x     = plot.scale("x").apply(mid) * scale;
    const flip  = mid &gt; (m.x0 + m.x1) / 2;
    const diff  = v.md - v.bl;
    const pct   = v.bl &gt; 0 ? ` (${sign(diff)}${(100 * diff / v.bl).toFixed(1)}%)` : "";
    tip.innerHTML = `
      &lt;strong&gt;${fmtTime(v.bin)} – ${fmtTime(v.bin + hover_bin)}&lt;/strong&gt;
      &lt;div&gt;&lt;span class="hover-swatch" style="background:${colors["Match day"]}"&gt;&lt;/span&gt;${m.day_label}: ${Math.round(v.md)} trips/min&lt;/div&gt;
      &lt;div&gt;&lt;span class="hover-swatch" style="background:${colors.Baseline}"&gt;&lt;/span&gt;Baseline: ${Math.round(v.bl)} trips/min&lt;/div&gt;
      &lt;div class="hover-diff"&gt;${sign(diff)}${diff.toFixed(1)}${pct}&lt;/div&gt;`;
    tip.style.left = `${x + (flip ? -14 : 14)}px`;
    tip.style.transform = flip ? "translate(-100%, -50%)" : "translateY(-50%)";
    tip.style.display = "block";
  });

  return wrap;
}
viewof area = Inputs.radio(area_list, {label: "Stations included", value: area_list[0]})
html`${matches.map(m =&gt; html`&lt;div class="card mb-4"&gt;
  &lt;div class="card-header"&gt;
    &lt;h4 class="mb-1"&gt;${m.title}&lt;/h4&gt;
    &lt;div class="text-muted small"&gt;${m.header}&lt;/div&gt;
  &lt;/div&gt;
  &lt;div class="card-body"&gt;
    &lt;div class="text-muted small fst-italic mb-2"&gt;Baseline: ${m.baseline}&lt;/div&gt;
    ${legend()}
    ${matchChart(m, area, width - 34)}
  &lt;/div&gt;
&lt;/div&gt;`)}`
